// Reine Regelnuebersicht, nur GET, rein lesend (HUMAN_IN_THE_LOOP_ARCHITECTURE.md Abschnitt 2:
// "Regeluebersicht ueber alle drei Versionierungsstile, rein lesend"). Ein SELECT mit einer
// JSON-Spalte je Kategorie - gleicher Trick wie die anderen Human-in-the-Loop-Seiten.
const sql = `SELECT
    (SELECT json_agg(row_to_json(x)) FROM (
       SELECT weight_key, weight_value, version, activated_at, activated_by, source_proposal_id
       FROM trading.scoring_weights WHERE active = TRUE
       ORDER BY weight_key
     ) x) AS scoring_weights,

    (SELECT json_agg(row_to_json(x)) FROM (
       SELECT strategy, combined_regime, fit_multiplier, blocked, rule_version, notes
       FROM trading.strategy_regime_matrix WHERE active = TRUE
       ORDER BY strategy, combined_regime
     ) x) AS regime_matrix,

    (SELECT json_agg(row_to_json(x)) FROM (
       SELECT strategy, parameter_key, parameter_value, version, updated_at
       FROM trading.strategy_parameters
       ORDER BY strategy, parameter_key
     ) x) AS strategy_parameters,

    (SELECT json_agg(row_to_json(x)) FROM (
       SELECT strategy, aktiv, deactivated_at, deactivated_reason
       FROM trading.strategy_status
       ORDER BY strategy
     ) x) AS strategy_status,

    (SELECT json_agg(row_to_json(x)) FROM (
       SELECT id, ticker, pattern, pattern_type, match_scope, reason, hit_count, last_hit_at, aktiv, created_at
       FROM trading.news_match_exclusions
       ORDER BY aktiv DESC, hit_count DESC NULLS LAST
       LIMIT 40
     ) x) AS news_ausschluesse;`;

return [{ json: { sql } }];

const row = $input.first().json;
let nav = {};
try { nav = $('Nav laden').first().json; } catch (e) { nav = {}; }

function esc(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function fmtDate(v) {
  if (!v) return '-';
  return new Date(v).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
}

const CSS = 'body{font-family:sans-serif;background:#0f1115;color:#e6e6e6;margin:0;padding:32px;max-width:1100px;margin:0 auto;}'
  + 'h1{font-size:22px;color:#fff;margin-bottom:4px;} h2{font-size:15px;color:#fff;margin-top:0;margin-bottom:8px;}'
  + '.meta{color:#9aa0a6;font-size:13px;margin-bottom:20px;} .hint{color:#9aa0a6;font-size:12px;margin-top:8px;}'
  + '.section{background:#181b21;border:1px solid #2a2d34;border-radius:8px;padding:16px 20px;margin-bottom:14px;overflow-x:auto;}'
  + 'table{width:100%;border-collapse:collapse;font-size:12px;}'
  + 'th{text-align:left;color:#9aa0a6;font-weight:600;font-size:10px;text-transform:uppercase;padding:4px 10px 6px 0;border-bottom:1px solid #2a2d34;}'
  + 'td{padding:6px 10px 6px 0;border-bottom:1px solid #22242a;white-space:nowrap;}'
  + 'tr:last-child td{border-bottom:none;}'
  + '.badge{display:inline-block;padding:2px 8px;border-radius:999px;font-size:11px;font-weight:600;}'
  + '.badge.ok{background:#1c3a2a;color:#6bcf8e;} .badge.warn{background:#3a2c1c;color:#e0a854;}'
  + '.badge.danger{background:#3a1c1c;color:#e0665a;} .badge.muted{background:#22242a;color:#7a7d84;}'
  + '.section-empty{color:#7a7d84;font-size:12px;font-style:italic;}';

const NAVBAR_LINKS = '<div style="background:#232323;border:1px solid #444;border-radius:6px;padding:8px 14px;margin-bottom:20px;display:flex;flex-wrap:wrap;gap:4px 16px;font-size:13px;"><a href="/webhook/aktien-status" style="color:#8ab4f8;text-decoration:none;">Status</a></div>';

function pageWrap(title, body) {
  return '<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><title>' + esc(title) + '</title><style>' + CSS + '</style></head><body>'
    + (nav && nav.navHtml ? nav.navHtml : NAVBAR_LINKS)
    + body
    + '</body></html>';
}

function table(titel, hinweis, items, headers, rowFn) {
  if (!items || items.length === 0) {
    return '<div class="section"><h2>' + esc(titel) + '</h2><div class="section-empty">Keine Eintraege.</div></div>';
  }
  return '<div class="section"><h2>' + esc(titel) + ' (' + items.length + ')</h2>'
    + '<table><thead><tr>' + headers.map(h => '<th>' + esc(h) + '</th>').join('') + '</tr></thead>'
    + '<tbody>' + items.map(rowFn).join('') + '</tbody></table>'
    + (hinweis ? '<div class="hint">' + hinweis + '</div>' : '')
    + '</div>';
}

// News-Ausschlussregeln haben KEIN gespeichertes ACTIVE/REVIEW_REQUIRED/DISABLED-Statusmodell
// (bestaetigt in HUMAN_IN_THE_LOOP_REVIEW.md, Fund 9/125) - hier nur ein rein clientseitig
// abgeleitetes Label aus aktiv/hit_count/last_hit_at, keine gespeicherte Groesse.
function abgeleiteterStatus(r) {
  if (!r.aktiv) return { label: 'deaktiviert', klass: 'muted' };
  if (!r.hit_count || r.hit_count === 0) return { label: 'ungenutzt', klass: 'warn' };
  return { label: 'aktiv genutzt', klass: 'ok' };
}

const scoringHtml = table('Scoring-Gewichte (aktiv)',
  'Versionierung: trading.scoring_weights.active (genau eine aktive Zeile je weight_key). Freigabe ausschliesslich ueber Lernvorschlag-Freigabe (Workflow 12).',
  row.scoring_weights, ['Key', 'Wert', 'Version', 'Aktiviert am', 'Von'],
  w => '<tr><td>' + esc(w.weight_key) + '</td><td>' + esc(w.weight_value) + '</td><td>' + esc(w.version) + '</td><td>' + fmtDate(w.activated_at) + '</td><td>' + esc(w.activated_by || '-') + '</td></tr>'
);

const regimeHtml = table('Strategie-Regime-Matrix (aktiv)',
  'Versionierung: trading.strategy_regime_matrix.active (sql/067). fit_multiplier skaliert die Eignung (1=voll geeignet, 0=blockiert).',
  row.regime_matrix, ['Strategie', 'Regime', 'Eignung', 'Blockiert', 'Version', 'Notiz'],
  r => '<tr><td>' + esc(r.strategy) + '</td><td>' + esc(r.combined_regime) + '</td><td>' + esc(r.fit_multiplier) + '</td>'
    + '<td>' + (r.blocked ? '<span class="badge danger">ja</span>' : '<span class="badge ok">nein</span>') + '</td>'
    + '<td>' + esc(r.rule_version) + '</td><td>' + esc(r.notes || '-') + '</td></tr>'
);

const paramsHtml = table('Strategie-Parameter',
  'Ueberschreibbar in-place (kein Versions-Verlauf), version-Spalte wird bei Freigabe erhoeht. Quelle: Lernvorschlagstyp time_stop_change/Multiplikator-Anpassung ueber Workflow 12.',
  row.strategy_parameters, ['Strategie', 'Parameter', 'Wert', 'Version', 'Geaendert am'],
  p => '<tr><td>' + esc(p.strategy) + '</td><td>' + esc(p.parameter_key) + '</td><td>' + esc(p.parameter_value) + '</td><td>' + esc(p.version) + '</td><td>' + fmtDate(p.updated_at) + '</td></tr>'
);

const statusHtml = table('Strategie-Status',
  'Einzige Stelle, um eine ganze Strategiefamilie global zu deaktivieren (Lernvorschlagstyp strategy_deactivation).',
  row.strategy_status, ['Strategie', 'Aktiv', 'Deaktiviert am', 'Grund'],
  s => '<tr><td>' + esc(s.strategy) + '</td><td>' + (s.aktiv ? '<span class="badge ok">aktiv</span>' : '<span class="badge danger">deaktiviert</span>') + '</td>'
    + '<td>' + fmtDate(s.deactivated_at) + '</td><td>' + esc(s.deactivated_reason || '-') + '</td></tr>'
);

const newsHtml = table('News-Ausschlussregeln (False-Positive-Filter, Top 40)',
  'Status-Spalte ist ABGELEITET (aus aktiv/hit_count), nicht gespeichert - es gibt noch kein ACTIVE/REVIEW_REQUIRED/DISABLED-Feld in der Datenbank. Aenderungen ueber Workflow 16c/16d, nie automatisch.',
  row.news_ausschluesse, ['Ticker', 'Pattern', 'Typ', 'Treffer', 'Letzter Treffer', 'Status'],
  r => {
    const s = abgeleiteterStatus(r);
    return '<tr><td>' + esc(r.ticker) + '</td><td>' + esc(r.pattern) + '</td><td>' + esc(r.pattern_type) + '</td>'
      + '<td>' + esc(r.hit_count ?? 0) + '</td><td>' + fmtDate(r.last_hit_at) + '</td>'
      + '<td><span class="badge ' + s.klass + '">' + s.label + '</span></td></tr>';
  }
);

const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const html = pageWrap('Regeln', ''
  + '<h1>Regeln</h1>'
  + '<div class="meta">Stand: ' + now + ' &middot; Regeluebersicht ueber alle Versionierungsstile - rein lesend, jede Aenderung laeuft weiterhin ueber Vorschlag &rarr; Pruefen &rarr; Simulieren &rarr; OOS &rarr; Freigeben &rarr; Aktiv (Workflow 12), nie hier direkt.</div>'
  + scoringHtml + regimeHtml + paramsHtml + statusHtml + newsHtml
);

return [{ json: { html } }];
